/* サッカーやろうぜ！ — playable browser prototype */
const $ = (s, root=document) => root.querySelector(s);
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatMoney = n => `¥${Math.round(n).toLocaleString('ja-JP')}万`;
const clubNames = ['北星ユナイテッド','港町マリナーズ','翠丘フォレスト','南城ブレイズ','青葉アスレチック','西都オリオンズ','白波FC','雷門ヴォルテックス','星見ローヴァーズ','東原レガシー','紅葉スパーク','銀嶺アルピーヌ'];
const lastNames = ['佐伯','高野','三浦','石川','野村','遠藤','伊藤','水野','秋山','桐生','松田','森','久保','西村','大島','小野','青木','橘','藤堂','中村','香川','日向','杉本','黒田','永井','柴崎','村上','林','斉藤','北川'];
const firstNames = ['翔','蓮','湊','悠真','大和','陽斗','樹','海斗','颯太','蒼','拓海','陸','律','優斗','仁','晴人','一輝','朝陽','翼','創'];
const positions = ['GK','CB','CB','RB','LB','DMF','CMF','AMF','RW','LW','CF','GK','CB','SB','CMF','AMF','CF','WG'];
const formations = {
  '4-3-3': ['GK','LB','CB','CB','RB','DMF','CMF','AMF','LW','CF','RW'],
  '4-4-2': ['GK','LB','CB','CB','RB','LM','CMF','CMF','RM','CF','CF'],
  '3-5-2': ['GK','CB','CB','CB','LM','DMF','CMF','AMF','RM','CF','CF']
};
const nav = [['home','⌂','ホーム'],['team','♙','チーム'],['tactics','⬡','戦術'],['training','↗','育成'],['transfers','⇄','移籍'],['club','▣','クラブ'],['league','▤','大会'],['history','◷','歴史'],['settings','⚙','設定']];
let state = null, view = 'home', activeMatch = null, matchTimer = null, toastTimer = null, filter = 'all';

function random(){ let x=state.seed|0; x ^= x<<13; x ^= x>>>17; x ^= x<<5; state.seed=x|0; return (x>>>0)/4294967296; }
function rand(min,max){return Math.floor(random()*(max-min+1))+min}
function choice(arr){return arr[rand(0,arr.length-1)]}
function clamp(n,a,b){return Math.max(a,Math.min(b,n))}
function avg(arr){return arr.reduce((a,b)=>a+b,0)/Math.max(1,arr.length)}
function makePlayer(id,pos){
  const base=rand(47,70)+(pos==='GK'?1:0), age=rand(17,32);
  const player={id,name:`${choice(lastNames)} ${choice(firstNames)}`,pos,age,training:'balanced',number:id+1,ovr:base,shoot:clamp(base+rand(-14,14),25,95),pass:clamp(base+rand(-13,13),25,95),defend:clamp(base+rand(-14,14),25,95),speed:clamp(base+rand(-12,12),25,95),potential:clamp(base+rand(7,24),54,95),stamina:rand(78,100),form:rand(57,90),morale:rand(65,90),xp:0,wage:rand(45,145),goals:0,apps:0};
  enrichPlayer(player);
  return player;
}
function makeFixtures(){
  const ids=Array.from({length:12},(_,i)=>i), rounds=[];
  for(let r=0;r<11;r++){
    const games=[]; for(let i=0;i<6;i++){const a=ids[i],b=ids[11-i];games.push(r%2===0?[a,b]:[b,a])}
    rounds.push(games); ids.splice(1,0,ids.pop());
  }
  return rounds.concat(rounds.map(g=>g.map(([a,b])=>[b,a])));
}
function freshState(name='北星ユナイテッド'){
  state={schemaVersion:1,seed:(Date.now()|0)||1,clubName:name.slice(0,24),season:1,division:4,round:0,cash:4200,fans:1700,training:'balanced',formation:'4-3-3',tempo:50,press:50,style:'balanced',facilities:{training:1,scouting:1,stadium:1},players:[],clubs:[],fixtures:makeFixtures(),table:[],results:[],history:[],news:[],lastMatch:null,lastGrowth:null,market:[]};
  state.players=positions.map((p,i)=>makePlayer(i,p));
  state.clubs=clubNames.map((name,i)=>({id:i,name:i===0?state.clubName:name,strength:i===0?61:rand(51,67),color:['#d6f487','#f2a86e','#85c8f3','#e994a6','#d1b6f2'][i%5]}));
  state.table=state.clubs.map(c=>({id:c.id,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0}));
  state.market=Array.from({length:5},(_,i)=>makeMarketPlayer(i));
  state.news=[news('新しいシーズンが始まりました。監督として最初の一歩を踏み出しましょう。')];
  return state;
}
function makeMarketPlayer(i){const pos=choice(['CB','CMF','CF','WG','SB','DMF','GK']);const p=makePlayer(1000+i+rand(1,9999),pos),previous=p.ovr;p.ovr=clamp(p.ovr+rand(1,10)+(state.facilities.scouting-1)*2,49,85);const bonus=Math.round((p.ovr-previous)*.7);for(const key of ['shoot','pass','defend','speed'])p[key]=clamp(p[key]+bonus,1,100);p.abilities=createAbilities(p);p.price=Math.round(p.ovr*p.ovr/3+rand(-200,300));return p}
function news(text){return {date:`${state.season}年目・第${state.round+1}節`,text}}
function addNews(text){state.news.unshift(news(text));state.news=state.news.slice(0,18)}
function sortedTable(){return [...state.table].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
function ownFixture(){return state.fixtures[state.round]?.find(g=>g.includes(0))}
function opponent(){const f=ownFixture();return f?state.clubs[f[0]===0?f[1]:f[0]]:null}
function starters(){return state.players.slice(0,11)}
function positionFit(actual,slot){if(actual===slot)return 1;const family=p=>p==='GK'?'g':['CB','LB','RB','SB'].includes(p)?'d':['DMF','CMF','AMF','LM','RM'].includes(p)?'m':'a';return family(actual)===family(slot)?.94:.78}
function squadStrength(){return avg(starters().map((p,i)=>p.ovr*positionFit(p.pos,formations[state.formation][i])*(.65+.35*p.stamina/100)*(.85+.15*p.form/100)))+state.facilities.training*.4}
function teamStrength(id){return id===0?squadStrength():state.clubs[id].strength}
function roundLabel(){return `${state.season}年目 · 第${Math.min(state.round+1,22)}節`}

function openDb(){return new Promise((resolve,reject)=>{if(!indexedDB)return reject(Error('IndexedDB unavailable'));const req=indexedDB.open('soccer-yarouze',1);req.onupgradeneeded=()=>req.result.createObjectStore('saves');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function save(){if(!state)return;try{const db=await openDb();await new Promise((resolve,reject)=>{const tx=db.transaction('saves','readwrite');tx.objectStore('saves').put(state,'career');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}catch(e){console.warn('保存できませんでした',e);showToast('保存できませんでした。JSONでバックアップしてください。')}}
async function load(){try{const db=await openDb();const value=await new Promise((resolve,reject)=>{const tx=db.transaction('saves','readonly');const req=tx.objectStore('saves').get('career');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return value}catch(e){return null}}
async function clearSave(){try{const db=await openDb();await new Promise((resolve,reject)=>{const tx=db.transaction('saves','readwrite');tx.objectStore('saves').delete('career');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}catch(e){console.warn('セーブ削除に失敗しました',e)}}
function showToast(message){let el=$('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.append(el)}el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3300)}
function persist(){save()}
function navHTML(){return nav.map(([id,icon,label])=>`<button class="nav-btn ${view===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}
function shell(content){const rank=sortedTable().findIndex(t=>t.id===0)+1;return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">⚽</div><div><strong>サッカーやろうぜ！</strong><small>FOOTBALL MANAGER</small></div></div><div><div class="nav-label">CLUB MENU</div><nav class="nav-list">${navHTML()}</nav></div><div class="sidebar-bottom">架空のアステリアリーグを<br>あなたの采配で駆け上がろう。</div></aside><main class="main"><div class="topbar"><div class="club-id"><div class="crest">${escapeHTML(state.clubName.slice(0,1))}</div><div><strong>${escapeHTML(state.clubName)}</strong><span>アステリア ${state.division}部 · ${roundLabel()}</span></div></div><div class="topbar-right"><span>リーグ ${rank}位</span><div class="pill">観客 ${state.fans.toLocaleString('ja-JP')}人</div><div class="cash">${formatMoney(state.cash)}</div></div></div><nav class="mobile-nav">${navHTML()}</nav><div class="content">${content}</div></main></div>`}
function pageHead(kicker,title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`}
function card(title,content,extra=''){return `<section class="card card-pad"><div class="card-title"><h2>${title}</h2>${extra}</div>${content}</section>`}
function metric(label,value,detail=''){return `<div class="metric"><span>${label}</span><strong>${value}</strong><em>${detail}</em></div>`}
function home(){const opp=opponent(),f=ownFixture(),rank=sortedTable().findIndex(t=>t.id===0)+1;const top=sortedTable().slice(0,5);return `${pageHead('CLUB DASHBOARD','クラブホーム','チームを見て、試合を始めましょう。')}<div class="grid home-grid"><div class="panel-stack"><div class="card next-match"><div class="match-meta">${opp?`NEXT MATCH · 第${state.round+1}節 · ${f[0]===0?'HOME':'AWAY'}`:'SEASON COMPLETE'}</div><div class="versus"><div class="team-name"><div class="mini-crest">${escapeHTML(state.clubName.slice(0,1))}</div>${escapeHTML(state.clubName)}</div><b>VS</b><div class="team-name" style="text-align:right"><div class="mini-crest rival" style="margin-left:auto">${escapeHTML((opp?.name||'次シーズン').slice(0,1))}</div>${escapeHTML(opp?.name||'次シーズン')}</div></div><button class="btn primary" data-action="${opp?'startMatch':'nextSeason'}">${opp?'▶ 試合を始める':'次のシーズンへ進む →'}</button></div><div class="metric-row">${metric('リーグ順位',`${rank}位`,'/ 12クラブ')}${metric('勝点',state.table[0].pts,'PTS')}${metric('チーム戦力',Math.round(squadStrength()),'OVR')}${metric('残り試合',Math.max(0,22-state.round),'MATCHES')}</div>${card('クラブニュース',`<div class="news-list">${state.news.slice(0,5).map(n=>`<div class="news-item"><time>${escapeHTML(n.date)}</time>${escapeHTML(n.text)}</div>`).join('')}</div>`)}</div><div class="panel-stack">${card('現在の順位',leagueTable(top,true),`<button class="btn ghost sm" data-view="league">全体を見る →</button>`)}${card('次への準備',`<div class="news-list"><div class="news-item">先発選手 <b>${starters().length}/11</b> 人 ・ GK <b>${starters().filter(p=>p.pos==='GK').length}</b> 人</div><div class="news-item">平均スタミナ <b>${Math.round(avg(starters().map(p=>p.stamina)))}%</b></div><div class="news-item">練習方針 <b>選手ごとに設定</b></div><div class="news-item">フォーメーション <b>${state.formation}</b></div></div><div class="btn-row" style="margin-top:16px"><button class="btn sm" data-view="team">選手を確認</button><button class="btn sm" data-view="tactics">戦術を調整</button></div>`)}</div></div>`}
function leagueTable(rows=sortedTable(),compact=false){return `<div class="table-wrap"><table><thead><tr><th>#</th><th>クラブ</th><th>試</th><th>勝</th><th>分</th><th>負</th><th>得失</th><th>勝点</th></tr></thead><tbody>${rows.map(t=>`<tr class="${t.id===0?'me':''}"><td class="rank">${sortedTable().findIndex(x=>x.id===t.id)+1}</td><td>${escapeHTML(state.clubs[t.id].name)}</td><td>${t.p}</td><td>${t.w}</td><td>${t.d}</td><td>${t.l}</td><td>${t.gf-t.ga>=0?'+':''}${t.gf-t.ga}</td><td><b>${t.pts}</b></td></tr>`).join('')}</tbody></table></div>`}
function staminaBar(value){return `<span class="bar ${value<55?'low':''}"><i style="width:${value}%"></i></span>${value}%`}
function fieldSlots(){const f=state.formation;let rows=f==='4-3-3'?[1,4,3,3]:f==='4-4-2'?[1,4,4,2]:[1,3,5,2];const xs=[10,31,60,85];let result=[],i=0;rows.forEach((n,r)=>{for(let j=0;j<n;j++)result.push({x:xs[r],y:((j+1)/(n+1))*100,player:state.players[i++]})});return result}
function tactics(){return `${pageHead('MATCH PLAN','戦術ボード','フォーメーションとプレー方針は次の試合から反映されます。')}<div class="split"><div class="card card-pad"><div class="card-title"><h2>先発フォーメーション</h2><span>${state.formation}</span></div><div class="pitch-box"><div class="pitch-lines"></div><div class="pitch-spot"></div>${fieldSlots().map(s=>`<div class="formation-player" style="left:${s.x}%;top:${s.y}%">${s.player.number}<small>${escapeHTML(s.player.name.split(' ')[0])}</small></div>`).join('')}</div><p class="subtle">位置適性の影響は試合の判定に反映されます。選手の入れ替えはチーム画面から行えます。</p></div><div class="card card-pad"><div class="card-title"><h2>監督の指示</h2></div><label class="label">フォーメーション</label><select class="field" id="formation" style="width:100%;margin-bottom:20px">${Object.keys(formations).map(f=>`<option ${state.formation===f?'selected':''}>${f}</option>`).join('')}</select><div class="tactic-group"><div class="form-line"><label class="label">攻撃テンポ</label><b id="tempo-value">${state.tempo}</b></div><input id="tempo" type="range" min="0" max="100" value="${state.tempo}"><div class="tactic-help">高いほど攻撃回数が増えますが、疲労も溜まりやすくなります。</div></div><div class="tactic-group"><div class="form-line"><label class="label">プレス強度</label><b id="press-value">${state.press}</b></div><input id="press" type="range" min="0" max="100" value="${state.press}"><div class="tactic-help">高いほどボールを奪いやすくなりますが、体力を消費します。</div></div><label class="label">攻撃方針</label><select class="field" id="style" style="width:100%;margin-bottom:20px"><option value="balanced" ${state.style==='balanced'?'selected':''}>バランス</option><option value="possession" ${state.style==='possession'?'selected':''}>ポゼッション</option><option value="counter" ${state.style==='counter'?'selected':''}>カウンター</option></select><button class="btn primary" data-action="saveTactics">戦術を保存</button></div></div>`}
function trainingLabel(){return {balanced:'バランス',attack:'攻撃',defense:'守備',fitness:'フィジカル',recovery:'回復'}[state.training]||'バランス'}
function transfers(){return `${pageHead('TRANSFER MARKET','移籍市場','限られた予算で新しい戦力を迎えましょう。')}<div class="card card-pad"><div class="card-title"><h2>獲得候補</h2><span>現在の予算 ${formatMoney(state.cash)}</span></div><div class="table-wrap"><table><thead><tr><th>選手</th><th>位置</th><th>年齢</th><th>OVR</th><th>将来性</th><th>移籍金</th><th></th></tr></thead><tbody>${state.market.map(p=>`<tr><td><div class="player-cell">${portraitSVG(p)}<b>${escapeHTML(p.name)}</b></div></td><td>${p.pos}</td><td>${p.age}</td><td>${rankBadgeHTML(p.ovr,'総合')}</td><td>${rankBadgeHTML(p.potential,'将来性の推定')}</td><td>${formatMoney(p.price)}</td><td><button class="btn sm" data-action="sign" data-id="${p.id}" ${state.cash<p.price?'disabled':''}>獲得する</button></td></tr>`).join('')}</tbody></table></div><p class="subtle">獲得した選手は控えに加入します。試合へ起用するにはチーム画面で入れ替えてください。</p></div>`}
function club(){const invest=(id,title,desc,cost)=>`<div class="investment"><strong>${title} · Lv.${state.facilities[id]}</strong><p>${desc}</p><span class="finance">${formatMoney(cost)}</span><button class="btn sm" data-action="invest" data-id="${id}" ${state.cash<cost?'disabled':''}>強化する</button></div>`;return `${pageHead('CLUB MANAGEMENT','クラブ経営','資金を使ってクラブの将来を整えます。')}<div class="metric-row" style="margin-bottom:16px">${metric('運営資金',formatMoney(state.cash))}${metric('ファン',state.fans.toLocaleString('ja-JP')+'人')}${metric('ホーム入場料',formatMoney(Math.round(state.fans*.04)))}${metric('所属',state.division+'部')}</div>${card('施設投資',`<div class="list-grid">${invest('training','練習施設','練習の成長効率が上がります。',1200*state.facilities.training)}${invest('scouting','スカウト網','次のシーズンの獲得候補が強くなります。',1000*state.facilities.scouting)}${invest('stadium','スタジアム','ホーム収入とファンの増加が伸びます。',1600*state.facilities.stadium)}</div>`)}<div class="footer-note">支出・収入は試合後に更新されます。選手の年俸はシーズン終了時に支払います。</div>`}
function league(){const fixtures=state.fixtures.map((games,i)=>({i,game:games.find(g=>g.includes(0))}));return `${pageHead('ASTERIA LEAGUE','大会・順位表',`アステリア ${state.division}部 · 12クラブ · 全22節`)}<div class="split"><div class="card card-pad"><div class="card-title"><h2>リーグ順位</h2><span>第${state.round}節終了</span></div>${leagueTable()}</div><div class="card card-pad"><div class="card-title"><h2>今季の日程</h2></div><div class="calendar">${fixtures.map(x=>`<div class="fixture ${x.i<state.round?'done':''}"><strong>第${x.i+1}節 ${x.i===state.round?'●':''}</strong>${escapeHTML(state.clubs[x.game[0]===0?x.game[1]:x.game[0]].name)}<br>${x.game[0]===0?'HOME':'AWAY'}</div>`).join('')}</div></div></div>`}
function history(){return `${pageHead('CLUB HISTORY','クラブの歴史','シーズンの記録がここに積み重なります。')}<div class="split">${card('シーズン記録',state.history.length?state.history.map(h=>`<div class="news-item"><b>${h.season}年目 · ${h.division}部 ${h.rank}位</b><br>${h.points}勝点 · ${h.wins}勝 ${h.draws}分 ${h.losses}敗${h.promoted?' · 昇格':''}</div>`).join(''):'<div class="empty">シーズンを終えると記録が表示されます。</div>')}${card('最近の試合',state.results.length?state.results.slice(0,8).map(r=>`<div class="news-item">第${r.round}節　${escapeHTML(r.home)} ${r.hg} - ${r.ag} ${escapeHTML(r.away)}</div>`).join(''):'<div class="empty">まだ試合の記録がありません。</div>')}</div>`}
function settings(){return `${pageHead('SAVE DATA','設定とセーブ','データはこのブラウザに自動保存されます。')}<div class="split">${card('セーブデータ',`<p class="subtle">別の端末で続ける場合は JSON ファイルを書き出し、読み込んでください。</p><div class="btn-row"><button class="btn primary" data-action="export">JSONを書き出す</button><button class="btn" data-action="import">JSONを読み込む</button><input id="import-file" type="file" accept=".json,application/json" hidden></div>`)}${card('新しく始める',`<p class="subtle">現在のデータを上書きして最初から始めます。必要なら先にバックアップしてください。</p><button class="btn danger" data-action="reset">新規ゲーム</button>`)}</div><div class="footer-note">完全無料 · 広告なし · ログイン不要。セーブはサーバーへ送信されません。</div>`}
function styleLabel(v){return {balanced:'バランス',possession:'ポゼッション',counter:'カウンター'}[v]}
function render(){document.body.classList.toggle('in-match',view==='match'&&!!activeMatch);const html=state?shell(view==='match'?matchView():({home,team,tactics,training,transfers,club,league,history,settings}[view]||home)()):intro();$('#app').innerHTML=html;if(view==='match'&&activeMatch)drawMatch()}
function intro(){return `<div class="overlay" style="position:static;min-height:100vh"><div class="dialog"><div class="eyebrow">NEW CAREER</div><h2>あなたのクラブを、伝説へ。</h2><p>アステリア4部から始まるサッカー監督生活。選手を育て、戦術を練り、リーグの頂点を目指しましょう。</p><label class="label" for="club-name">クラブ名</label><input class="field" id="club-name" maxlength="24" value="北星ユナイテッド"><button class="btn primary" data-action="newGame" style="width:100%">監督として始める →</button><p style="text-align:center;font-size:10px">無料 · 広告なし · ログイン不要</p></div></div>`}
function showDialog(html){const overlay=document.createElement('div');overlay.className='overlay';overlay.id='dialog-overlay';overlay.innerHTML=`<div class="dialog">${html}</div>`;document.body.append(overlay)}
function closeDialog(){$('#dialog-overlay')?.remove()}

function updateTable(home,away,hg,ag){for(const [id,gf,ga] of [[home,hg,ag],[away,ag,hg]]){const t=state.table[id];t.p++;t.gf+=gf;t.ga+=ga;if(gf>ga){t.w++;t.pts+=3}else if(gf===ga){t.d++;t.pts++}else t.l++}}
function aiResult(home,away){const d=teamStrength(home)-teamStrength(away);const goals=(strength)=>{let g=0;for(let i=0;i<4;i++)if(random()<clamp(.27+strength/150,.12,.5))g++;return g};return [goals(d),goals(-d)]}
function nextSeason(){if(state.round<22)return;const rank=sortedTable().findIndex(t=>t.id===0)+1,promoted=rank<=2&&state.division>1;state.history.unshift({season:state.season,division:state.division,rank,points:state.table[0].pts,wins:state.table[0].w,draws:state.table[0].d,losses:state.table[0].l,promoted});const wages=state.players.reduce((n,p)=>n+p.wage,0);state.cash=Math.max(0,state.cash+2000+state.fans*.05-wages);if(promoted)state.division--;state.season++;state.round=0;state.fixtures=makeFixtures();state.table=state.clubs.map(c=>({id:c.id,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0}));for(const c of state.clubs)if(c.id!==0)c.strength=clamp(c.strength+rand(-3,4)+(promoted?5:0),45,90);for(const p of state.players){p.age++;p.stamina=clamp(p.stamina+20,45,100);if(p.age>32&&random()<.4)p.ovr=Math.max(35,p.ovr-1)}state.market=Array.from({length:5},(_,i)=>makeMarketPlayer(i));addNews(`${state.season}年目が開幕。前季は${rank}位${promoted?'で昇格を達成！':'でした。'}`);persist();render();showToast(promoted?`${state.division}部に昇格しました！`:'新シーズンが始まりました')}
function validateImport(x){return !!(x&&x.schemaVersion===1&&Array.isArray(x.players)&&x.players.length>=11&&x.players.every(p=>p&&typeof p.name==='string'&&Number.isFinite(p.ovr)&&Number.isFinite(p.stamina)&&typeof p.pos==='string')&&Array.isArray(x.clubs)&&x.clubs.length===12&&x.clubs.every((c,i)=>c&&c.id===i&&typeof c.name==='string'&&Number.isFinite(c.strength))&&Array.isArray(x.table)&&x.table.length===12&&x.table.every((t,i)=>t&&t.id===i&&Number.isFinite(t.pts))&&Array.isArray(x.fixtures)&&x.fixtures.length===22&&x.fixtures.every(round=>Array.isArray(round)&&round.length===6&&round.every(g=>Array.isArray(g)&&g.length===2&&g.every(id=>Number.isInteger(id)&&id>=0&&id<12)))&&Number.isInteger(x.round)&&x.round>=0&&x.round<=22&&Object.hasOwn(formations,x.formation)&&typeof x.clubName==='string'&&x.clubName.length<=24&&Number.isFinite(x.cash)&&Number.isInteger(x.seed)&&x.facilities&&Number.isFinite(x.facilities.training)&&Number.isFinite(x.facilities.stadium)&&Array.isArray(x.market)&&Array.isArray(x.history)&&Array.isArray(x.results)&&Array.isArray(x.news))}
function exportSave(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`soccer-yarouze-season-${state.season}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('セーブデータを書き出しました')}
async function importSave(file){try{const x=JSON.parse(await file.text());if(!validateImport(x))throw Error('形式が正しくありません');clearInterval(matchTimer);activeMatch=null;state=x;enrichRoster(state);view='home';await save();render();showToast('セーブデータを読み込みました')}catch(e){showToast('読み込み失敗: '+e.message)}}

document.addEventListener('click',e=>{const b=e.target.closest('[data-view],[data-action]');if(!b)return;if(b.dataset.view){if(activeMatch&&b.dataset.view!=='match'){showToast('試合中は画面を切り替えられません');return}view=b.dataset.view;render();return}const action=b.dataset.action,id=Number(b.dataset.id);if(action==='newGame'){freshState($('#club-name')?.value.trim()||'北星ユナイテッド');view='home';persist();render()}if(action==='startMatch')startMatch();if(action==='nextSeason')nextSeason();if(action==='selectPlayer')playerDialog(id);if(action==='closeDialog')closeDialog();if(action==='swapPlayer'){const a=state.players.findIndex(p=>p.id===id),target=Number($('#swap-target')?.value),z=state.players.findIndex(p=>p.id===target);if(a>=0&&z>=0){[state.players[a],state.players[z]]=[state.players[z],state.players[a]];if(starters().filter(p=>p.pos==='GK').length!==1){[state.players[a],state.players[z]]=[state.players[z],state.players[a]];showToast('先発にGKを1人入れてください')}else{persist();closeDialog();render();showToast('先発を変更しました')}}}if(action==='saveTactics'){state.formation=$('#formation').value;state.tempo=Number($('#tempo').value);state.press=Number($('#press').value);state.style=$('#style').value;persist();render();showToast('戦術を保存しました')}if(action==='saveTraining'){state.training=$('#training').value;persist();render();showToast('練習方針を設定しました')}if(action==='sign'){const p=state.market.find(x=>x.id===id);if(p&&state.cash>=p.price){state.cash-=p.price;state.players.push(p);state.market=state.market.filter(x=>x.id!==id);addNews(`${p.name}を獲得しました。`);persist();render();showToast(`${p.name}が加入しました`)}}if(action==='invest'){const level=state.facilities[b.dataset.id],cost={training:1200,scouting:1000,stadium:1600}[b.dataset.id]*level;if(state.cash>=cost){state.cash-=cost;state.facilities[b.dataset.id]++;persist();render();showToast('施設を強化しました')}}if(action==='pause'&&activeMatch){activeMatch.paused=!activeMatch.paused;render()}if(action==='speed'&&activeMatch){activeMatch.speed=id;render()}if(action==='export')exportSave();if(action==='import')$('#import-file')?.click();if(action==='reset')showDialog(`<div class="eyebrow">NEW GAME</div><h2>最初から始めますか？</h2><p>現在のデータは上書きされます。必要なら先にJSONを書き出してください。</p><div class="btn-row"><button class="btn danger" data-action="confirmReset">新しく始める</button><button class="btn" data-action="closeDialog">キャンセル</button></div>`);if(action==='confirmReset'){clearInterval(matchTimer);activeMatch=null;state=null;closeDialog();clearSave();render()}});
document.addEventListener('change',e=>{if(e.target.id==='team-filter'){filter=e.target.value;render()}if(e.target.id==='import-file'&&e.target.files[0])importSave(e.target.files[0]);if(e.target.id==='match-style'&&activeMatch){state.style=e.target.value;persist();updateMatchUI();showToast('試合中の戦術を変更しました')}});
document.addEventListener('input',e=>{if(e.target.id==='tempo')$('#tempo-value').textContent=e.target.value;if(e.target.id==='press')$('#press-value').textContent=e.target.value});
window.addEventListener('beforeunload',()=>{if(state)save()});
(async()=>{const loaded=await load();if(validateImport(loaded)){state=loaded;if(enrichRoster(state))await save()}render()})();
